@pytest.fixture
def bake_spy(monkeypatch):
    """Records what the scene looked like at every bake pass, while the scene is set up for baking."""
    seen = []
    original = bake_module._run_bake_passes

    def spy(state, bake_type):
        scene = state["scene"]
        world_ = scene.world
        seen.append({
            "type": bake_type,
            "bake_lights": [(obj.data.energy, getattr(obj.data, "use_shadow", None)) for obj in scene.objects
                            if obj.name.startswith("BakeHairLight")],
            "visible": {obj.name for obj in scene.objects if obj.visible_get() and not obj.hide_render},
            "rendered": {obj.name for obj in scene.objects
                         if HairEditorService.is_rendered(obj, scene, bpy.context.view_layer)},
            "background": (tuple(world_.node_tree.nodes["Background"].inputs[0].default_value)
                           if world_ and world_.use_nodes and "Background" in world_.node_tree.nodes else None),
            "engine": scene.render.engine,
            })
        return original(state, bake_type)

    monkeypatch.setattr(bake_module, "_run_bake_passes", spy)
    return seen


