@pytest.mark.parametrize("asset, fur", _PICKER_ITEMS, ids=[item[0] for item in _PICKER_ITEMS])
def test_every_offered_asset_is_in_the_pack(asset, fur):
    """An item in a picker which is missing from the pack fails only when the user presses Apply."""
    installed = HairEditorService.is_fur_asset_installed() if fur else HairEditorService.is_hair_asset_installed()
    if not installed:
        pytest.skip("The hair editor asset pack is not installed")
    assert asset in pack_objects(fur)


def test_installed_pack_is_the_current_one():
    if not HairEditorService.is_hair_asset_installed():
        pytest.skip("The hair editor asset pack is not installed")
    assert not HairEditorService.is_hair_pack_outdated(), "the tests are written against the current asset pack"


def test_pack_asset_names_are_understood():
    """Sliders are matched to their asset by name, which an unlucky asset name could break (see hairproperties_test)."""
    if not HairEditorService.is_hair_asset_installed():
        pytest.skip("The hair editor asset pack is not installed")
    for asset, fur in _PICKER_ITEMS + [(HAIR_ASSET, False), (SECOND_HAIR_ASSET, False)]:
        prefix = hp.DYNAMIC_PREFIX_FUR if fur else hp.DYNAMIC_PREFIX
        definitions = hp.DYNAMIC_FUR_PROPS_DEFINITIONS if fur else hp.DYNAMIC_HAIR_PROPS_DEFINITIONS
        for name in list(definitions) + list(hp.DYNAMIC_CARDS_PROPS_DEFINITIONS):
            factory = hp.HairGetterSetterFactory(f"{prefix}{asset}_{name}", prefix=prefix, fur=fur)
            assert factory.hair_object_name == asset, f"{asset}_{name} is wired to '{factory.hair_object_name}'"
            assert factory.short_property_name == name


@pytest.mark.parametrize("asset, fur", _PICKER_ITEMS, ids=[item[0] for item in _PICKER_ITEMS])
def test_every_offered_asset_applies_and_deletes_cleanly(character, asset, fur):
    require_pack_asset(asset, fur=fur)
    # The implicit setup leaves its empty hair object (with its data and node group) on the character, which is intended
    hairsetup.ensure_hair_setup(character, bpy.context)
    counts = datablock_counts()
    hair_obj = apply_hair(character, asset, fur=fur)
    hair_name = hair_obj.name
    properties = FUR_PROPERTIES if fur else HAIR_PROPERTIES
    kind = "fur" if fur else "hair"
    assert properties.has_key(f"{hair_obj.name}_{kind}_asset_open", entity_reference=character)
    assert hair_obj.parent == character

    assert delete_hair(character, hair_name, fur=fur) == {'FINISHED'}
    assert hair_name not in [child.name for child in ObjectService.get_list_of_children(character)]
    assert not [key for key in properties.get_keys(character) if key.startswith(f"{asset}_")]
    leaked = leaked_since(counts)
    assert not leaked, f"applying and deleting {asset} left {leaked} behind"


