def test_apply_sets_the_asset_up(hair_character):
    basemesh, hair_obj, asset = hair_character.basemesh, hair_character.hair_obj, hair_character.asset_name
    assert hair_obj.type == 'CURVES'
    assert hair_obj.parent == basemesh
    assert hair_obj.data.surface == basemesh
    assert hair_obj[hp.PACK_NAME_PROPERTY] == HAIR_ASSET
    assert hair_obj.matrix_parent_inverse == Matrix.Identity(4), "groomed at the origin, so no parent inverse"

    for name, (modifier_name, attribute, _range) in hp.DYNAMIC_HAIR_PROPS_DEFINITIONS.items():
        expected = ModifierService.get_node_group_input(hair_obj.modifiers[modifier_name], attribute)
        assert hair_character.get(name) == pytest.approx(expected), f"{name} does not show what the asset has"
    for name in hp.DYNAMIC_HAIR_MATERIAL_PROPS_DEFINITIONS:
        assert HAIR_PROPERTIES.has_key(f"{asset}_{name}", entity_reference=basemesh)
    for name in list(hp.DYNAMIC_CARDS_CONFIG_PROPS_DEFINITIONS) + list(hp.DYNAMIC_CARDS_BAKE_PROPS_DEFINITIONS):
        assert HAIR_PROPERTIES.has_key(f"{asset}_{name}", entity_reference=basemesh), f"{name} was not created"
    assert not hair_character.flag("generated")
    assert not hair_character.flag("baked")
    assert hair_character.get("hair_asset_open") is False
    assert hairsetup.is_hair_setup(basemesh)


def test_apply_leaves_no_unused_images(character):
    """Asset packs carry the textures of every asset, only the ones this asset uses may stay."""
    require_pack_asset(HAIR_ASSET)
    before = {image.name for image in bpy.data.images}
    apply_hair(character, HAIR_ASSET)
    unused = [image.name for image in bpy.data.images if image.name not in before and image.users == 0]
    assert not unused


