@pytest.mark.parametrize("mode", [item[0] for item in cg.CARDS_MODE_ITEMS])
def test_cards_are_generated_in_every_mode(hair_character, mode):
    hair_character.set("cards_mode", mode)
    assert hair_character.run("generate_hair_cards_operator") == {'FINISHED'}
    card_obj = hair_character.card_obj
    assert card_obj is not None and card_obj.parent == hair_character.basemesh
    assert hair_character.flag("generated")
    assert hair_character.get("cards_mode") == mode, "the mode picked before converting has to be the one used"
    has_generator = hp.CARDS_MODIFIER_NAME in card_obj.modifiers
    assert has_generator == (mode != cg.CARDS_MODE_CLUSTER_BOX), "only cluster boxes are a finished mesh"

    probe = card_obj.copy()
    probe.data = card_obj.data.copy()
    link(probe)
    select(probe)
    bpy.ops.object.convert(target='MESH')
    assert len(probe.data.polygons) > 0, f"mode {mode} produced no cards"


