def test_failed_regenerate_keeps_the_old_cards(character):
    require_pack_asset(_EMPTY_ASSET)
    asset = AppliedAsset(character, apply_hair(character, _EMPTY_ASSET))
    try:
        assert asset.run("generate_hair_cards_operator") == {'FINISHED'}
        old_cards = asset.card_obj
        asset.set("cards_mode", cg.CARDS_MODE_CLUSTER_BOX)
        result, report = run_hardened(Regenerate, character,
                                      hair_asset=asset.asset_name, is_fur=False)
        assert result == {'CANCELLED'}
        assert asset.card_obj == old_cards, "a failed rebuild must not leave the asset without cards"
        assert not [obj for obj in bpy.data.objects if obj.name.endswith("_rebuilding")]
    finally:
        delete_hair(character, asset.asset_name)


def test_regenerate_keeps_the_settings_across_modes(hair_with_cards):
    """Mode changes need a rebuild, which used to reset every slider, as the values live in the replaced group."""
    counts = datablock_counts()
    hair_with_cards.set("cards_width", 0.111)
    hair_with_cards.set("cards_segments", 13)
    for mode in (cg.CARDS_MODE_TILES, cg.CARDS_MODE_RIBBON, cg.CARDS_MODE_CLUSTER_BOX,
                 cg.CARDS_MODE_CLUSTER_RIBBON, cg.CARDS_MODE_SHELL, cg.CARDS_MODE_TILES):
        hair_with_cards.set("cards_mode", mode)
        assert hair_with_cards.run("regenerate_hair_cards_operator") == {'FINISHED'}, mode
        assert hair_with_cards.card_obj is not None
        if mode in (cg.CARDS_MODE_TILES, cg.CARDS_MODE_RIBBON):
            assert hair_with_cards.get("cards_width") == pytest.approx(0.111), f"width lost in {mode}"
    assert hair_with_cards.get("cards_segments") == 13, "segments only exist in tiles, but have to survive the trip"
    node_group = hair_with_cards.card_obj.modifiers[hp.CARDS_MODIFIER_NAME].node_group
    assert node_group.name == f"{hair_with_cards.asset_name}_cards_{hp.CARDS_MODIFIER_NAME}", \
        "delete looks the group up by this name"
    assert not leaked_since(counts), "cycling through the modes left datablocks behind"


