def test_failed_bake_changes_nothing(hair_with_cards, tmp_path, monkeypatch, world):
    def broken(state, bake_type):
        raise RuntimeError("the render failed")

    monkeypatch.setattr(bake_module, "_run_bake_passes", broken)
    cards_before = hair_with_cards.card_obj
    materials = [slot.material for slot in hair_with_cards.hair_obj.material_slots]
    result, report = _bake(hair_with_cards, tmp_path)
    assert result == {'CANCELLED'}
    report.assert_reported('ERROR', "nothing was replaced")
    assert hair_with_cards.card_obj == cards_before
    assert hp.CARDS_MODIFIER_NAME in cards_before.modifiers, "the live cards keep their generator"
    assert not hair_with_cards.flag("baked")
    assert [slot.material for slot in hair_with_cards.hair_obj.material_slots] == materials
    assert _background(world) == pytest.approx((0.2, 0.3, 0.4, 1.0))
    assert not _temporary_bake_leftovers()


