def test_unbake_brings_the_editable_cards_back(hair_with_cards, tmp_path):
    hair_with_cards.set("cards_segments", 17)
    _bake(hair_with_cards, tmp_path)
    assert hair_with_cards.run("unbake_hair_operator") == {'FINISHED'}
    assert not hair_with_cards.flag("baked")
    assert hair_with_cards.flag("generated")
    card_obj = hair_with_cards.card_obj
    assert card_obj is not None and hp.CARDS_MODIFIER_NAME in card_obj.modifiers
    assert hair_with_cards.get("cards_segments") == 17, "the settings at bake time come back"
    assert not hair_with_cards.hair_obj.hide_render
    for name in hp.baked_image_names(hair_with_cards.asset_name):
        assert name not in bpy.data.images
    assert f"{hair_with_cards.asset_name}_baked" not in bpy.data.materials
    assert os.path.isfile(os.path.join(tmp_texture_dir(tmp_path), f"{hair_with_cards.asset_name}_texture.png")), \
        "files on disk are the user's, unbake leaves them alone"


