def test_body_shell(fur_character, tmp_path):
    """Fur grows out of the body, so a shell cut from those body faces is what it is baked onto."""
    fur = fur_character
    fur.set("cards_bake_target", cg.BAKE_TARGET_BODY_SHELL)
    assert fur.run("generate_hair_cards_operator") == {'FINISHED'}
    shell = fur.card_obj
    assert shell is not None and shell.type == 'MESH'
    assert 0 < len(shell.data.polygons) < len(fur.basemesh.data.polygons), "only the faces the fur grows from"
    assert hp.CARDS_MODIFIER_NAME in shell.modifiers
    assert fur.get("cards_body_height") == pytest.approx(0.006)

    result, report = _bake(fur, tmp_path, cards_body_edge_fade=True, cards_body_edge_fade_width=1)
    assert result == {'FINISHED'}, report.reports
    shell = fur.card_obj
    assert cg.SHELL_EDGE_FADE_ATTRIBUTE in shell.data.attributes
    material = shell.data.materials[0]
    assert bodyoverlay.find_tagged_node(material.node_tree, bodyoverlay.ROLE_EDGE_FADE) is not None
    assert not _temporary_bake_leftovers()

    assert fur.run("unbake_hair_operator") == {'FINISHED'}
    assert fur.card_obj is not None and fur.flag("generated")


def test_volume_shell_always_bakes_its_cutoff_maps(hair_character, tmp_path):
    hair_character.set("cards_mode", cg.CARDS_MODE_SHELL)
