def test_delete_removes_everything_of_the_asset(hair_with_cards, tmp_path):
    asset, basemesh = hair_with_cards.asset_name, hair_with_cards.basemesh
    second = AppliedAsset(basemesh, apply_hair(basemesh, SECOND_HAIR_ASSET)) \
        if SECOND_HAIR_ASSET in pack_objects() else None
    _bake(hair_with_cards, tmp_path)
    toggle_section_operator._OPEN_SECTIONS[(asset, "maps")] = True

    assert delete_hair(basemesh, asset) == {'FINISHED'}
    assert asset not in bpy.data.objects
    assert f"{asset}{hp.CARDS_OBJECT_SUFFIX}" not in bpy.data.objects
    assert f"{asset}_cards_{hp.CARDS_MODIFIER_NAME}" not in bpy.data.node_groups
    assert f"{asset}_baked" not in bpy.data.materials
    for name in hp.baked_image_names(asset):
        assert name not in bpy.data.images
    assert not [key for key in HAIR_PROPERTIES.get_keys(basemesh) if key.startswith(f"{asset}_")]
    assert hp.read_cards_settings(basemesh, asset) == {}
    assert not toggle_section_operator.is_open(asset, "maps")
    if second is not None:
        assert second.hair_obj.name in bpy.data.objects, "the other asset is not touched"
        assert HAIR_PROPERTIES.has_key(f"{second.asset_name}_length", entity_reference=basemesh)
        delete_hair(basemesh, second.asset_name)


def test_whole_lifecycle_leaves_nothing_behind(character, tmp_path):
    """Orphans are invisible in the viewport, but they bloat the file and keep textures alive forever."""
    require_pack_asset(HAIR_ASSET)
    apply_hair(character, HAIR_ASSET)
    delete_hair(character, HAIR_ASSET)  # the implicit setup only happens once
    counts = datablock_counts()

    asset = AppliedAsset(character, apply_hair(character, HAIR_ASSET))
    asset.run("generate_hair_cards_operator")
    _bake(asset, tmp_path, cards_bake_ao=True)
    asset.run("unbake_hair_operator")
    asset.set("cards_mode", cg.CARDS_MODE_RIBBON)
    asset.run("regenerate_hair_cards_operator")
    delete_hair(character, asset.asset_name)
    assert not leaked_since(counts)
